import React from 'react';
import { FaMoon, FaSun, FaBars } from 'react-icons/fa';
import { UserButton, useUser } from '@clerk/clerk-react';
import './Header.css';

const Header = ({ darkMode, toggleDarkMode, toggleSidebar }) => {
  const { user } = useUser();

  return (
    <header className="app-header">
      {/* Left Group: Menu button + CRM title */}
      <div className="branding">
        <button className="menu-btn" onClick={toggleSidebar}>
          <FaBars size={20} />
        </button>
        <h1 className="glitter-title">-CRM System-</h1>
      </div>

      {/* Right: Navigation + Controls */}
      <div className="header-right">
        <nav className="nav-tabs">
          <button
            className="nav-tab"
            onClick={() => window.location.reload()}
          >Home</button>
          <button
            className="nav-tab"
            onClick={() => window.location.hash = '#dashboard'}
          >Dashboard</button>
          <button
            className="nav-tab"
            onClick={() => window.location.hash = '#agents'}
          >Agents</button>
          <button
            className="nav-tab"
            onClick={() => window.location.hash = '#tasks'}
          >Tasks</button>
          <button
            className="nav-tab"
            onClick={() => window.location.hash = '#customers'}
          >Customers</button>
          <button
            className="nav-tab"
            onClick={() => window.location.hash = '#about'}
          >
            <FaInfoCircle style={{ marginRight: "6px", verticalAlign: "middle" }} /> About
          </button>
        </nav>

        <div className="header-controls">
          <span className="user-info">
            Welcome, {user?.firstName} {user?.lastName}
          </span>
          <span className="login-btn">
            <UserButton />
          </span>
          <span
            className="darkmode-toggle"
            onClick={toggleDarkMode}
            title="Toggle Dark Mode"
            role="button"
            tabIndex={0}
          >
            {darkMode ? <FaSun size={22} /> : <FaMoon size={22} />}
          </span>
        </div>
      </div>
    </header>
  );
};

export default Header;
